import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,R as c,S as l,V as u,_ as d,a as f,k as p,l as m,o as h,p as g,t as _,x as v}from"./shared-BLp3PbbW.js";import{n as y}from"./sparkles-DROpfoeS.js";import{t as b}from"./CodeEditor-DqHMt3P8.js";var x=e();function S({module:e}){return(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{chip:e??`Блок 7 · Python Deeper`,title:`Выбор формы и базовая композиция`,intro:`Подготовленная Task не означает, что весь Planner нужно превращать в набор классов. Разберём, когда достаточно словаря или функции, что класс получает от композиции и почему сотрудничество объектов не требует наследования.`,tags:[{icon:(0,x.jsx)(y,{size:14}),label:`выбор формы`},{icon:(0,x.jsx)(u,{size:14}),label:`сотрудничество объектов`},{icon:(0,x.jsx)(c,{size:14}),label:`связи объектов`}]}),(0,x.jsxs)(s,{number:`00`,title:`От подготовленной модели к выбору ответственности`,children:[(0,x.jsx)(o,{children:`По маршруту предыдущих занятий мы подготовили Task и разобрали преобразование в запись. Перед переходом проверим эту опору: одна Task отвечает за одну задачу, а рабочие операции Planner пока используют словари. Теперь выясним, когда отдельный объект полезен и как он поручает действие другому объекту.`}),(0,x.jsx)(p,{variant:`connected`,items:[{title:`Точка старта`,description:`По учебному маршруту в app.models подготовлена Task; операции и функциональный JSON пока работают со словарями. Проверяем это перед занятием.`},{title:`Новый вопрос`,description:`Как выбрать форму нового компонента и связать объекты, не приписывая им чужие обязанности?`},{title:`Результат`,description:`Мы различим словарь, функцию, класс и dataclass, проследим композицию и распределим роли частей Planner.`}]}),(0,x.jsx)(`p`,{children:`Подготовка модели не переключила CLI или JSON на объекты. Это полезная граница: мы можем рассматривать архитектурные решения отдельно от миграции. Сначала разберём критерии выбора, затем проследим один небольшой пример сотрудничества, а в конце вернёмся к знакомым обязанностям Planner.`})]}),(0,x.jsxs)(s,{number:`01`,title:`Выбираем форму по задаче, а не по престижу`,children:[(0,x.jsx)(o,{children:`У нас уже есть несколько способов представить работу программы. У каждого своя роль: словарь удобно передаёт данные, функция выполняет действие, класс связывает состояние одного объекта с его поведением, а dataclass сокращает повторяющийся код модели. Более новый синтаксис сам по себе не делает решение лучше.`}),(0,x.jsx)(`p`,{children:`Например, запись задачи в словаре прямо показывает значения, которые можно сохранить или передать дальше. Функция вроде проверки названия получает вход и возвращает результат; ей обычно не нужно помнить отдельное состояние между вызовами. Task, напротив, представляет одну задачу: её поля относятся к конкретному экземпляру, а методы меняют или описывают именно его. Dataclass уместен, когда такая модель состоит из объявленных полей и мы хотим убрать шаблон создания и сравнения. Он не выполняет за нас проверку правил и не открывает JSON.`}),(0,x.jsx)(`p`,{children:`Сравним формы по тому, что они несут в знакомом Planner:`}),(0,x.jsx)(t,{rows:[[`dict`,`Явная запись значений задачи; подходит для текущей границы JSON.`],[`function`,`Отдельное действие над переданными данными, например нормализация названия.`],[`обычный class`,`Состояние одного объекта и методы, работающие с ним.`],[`dataclass`,`Модель с полями и сгенерированным шаблонным поведением; предметные правила остаются явными.`]]}),(0,x.jsx)(b,{caption:`Запись и действие не требуют создавать новый объект`,code:`record = {"title": "  Хлеб  ", "is_done": False}
def normalize_title(text):
    return text.strip()

print(record["is_done"])
print(normalize_title(record["title"]))`}),(0,x.jsxs)(`p`,{children:[`Получим `,(0,x.jsx)(`code`,{children:`False`}),` и `,(0,x.jsx)(`code`,{children:`Хлеб`}),`. Словарь просто хранит два значения, функция очищает переданный текст. Никакой новый экземпляр ради очистки не нужен. У существующей Task другая задача: удерживать связанные поля одной записи и правила изменения её состояния. `,(0,x.jsx)(`code`,{children:`@dataclass`}),` остаётся классом Task, только Python генерирует обычный служебный код, например `,(0,x.jsx)(`code`,{children:`__init__`}),`. Сама аннотация типа поля автоматически не проверяет данные при выполнении.`]}),(0,x.jsx)(r,{tone:`info`,children:`Три вопроса перед созданием класса: что нужно помнить между вызовами, какое действие выполнять и кто вправе менять состояние? Словарь подходит для записи данных, функция для отдельного преобразования, класс для связанного состояния и поведения. Dataclass сокращает служебный код уже выбранного класса.`}),(0,x.jsx)(`p`,{children:`Можно представить функцию как краткий рецепт: мы передаём ингредиенты, получаем результат и не обязаны сохранять рядом отдельное состояние каждого запуска. Экземпляр Task больше похож на личную рабочую карточку: поля принадлежат одной задаче, а связанные действия обращаются к этой карточке. Граница аналогии важна: функция всё ещё может изменить переданный объект, а карточка не объясняет устройство Python. Сравнение помогает спросить, требуется ли компоненту собственное состояние и действия, а не назначить форму по внешнему сходству.`}),(0,x.jsxs)(`p`,{children:[`Проверим критерий на спорном решении: `,(0,x.jsx)(`code`,{children:`TitleNormalizer`}),`, который хранит лишь метод с`,(0,x.jsx)(`code`,{children:`text.strip()`}),`, не получает собственного состояния. Это не запрет на классы без состояния: здесь дополнительный экземпляр просто не решает новой задачи. В Task метод `,(0,x.jsx)(`code`,{children:`mark_done()`}),`, напротив, меняет статус именно выбранной задачи.`]}),(0,x.jsx)(l,{statement:(0,x.jsxs)(x.Fragment,{children:[`Для `,(0,x.jsx)(`code`,{children:`normalize_title`}),`, которая только очищает переданную строку, отдельный класс обязателен, потому что в Planner уже есть класс Task.`]}),isTrue:!1,explanation:`Мы выбираем форму отдельно для каждой ответственности. Одна функция здесь проще: ей не требуется собственное состояние.`})]}),(0,x.jsxs)(s,{number:`02`,title:`Композиция связывает объекты через вызов`,children:[(0,x.jsx)(o,{children:`Композиция здесь означает сотрудничество объектов: один объект хранит ссылку на другой и вызывает его метод. Объект, который обращается за помощью, назовём потребителем, а переданный ему объект зависимостью.`}),(0,x.jsxs)(`p`,{children:[`Создадим учебный ценник `,(0,x.jsx)(`code`,{children:`PriceTag`}),`. Он знает, когда показать стоимость, но не выбирает внешний вид строки. Отдельный `,(0,x.jsx)(`code`,{children:`PriceFormatter`}),` принимает число и возвращает текст. Передача готового форматировщика в `,(0,x.jsx)(`code`,{children:`__init__`}),` называется передачей зависимости; это обычный аргумент конструктора.`]}),(0,x.jsx)(`p`,{children:`Представим работника с ценником и отдельный принтер: первый просит напечатать цену, второй выбирает вид надписи. В коде «принтер» ничего не печатает: метод только возвращает строку. Проследим оба направления.`}),(0,x.jsx)(_,{caption:`Ценник передаёт число форматировщику и получает строку`,children:(0,x.jsxs)(h,{label:`Путь вызова PriceTag.show(100)`,children:[(0,x.jsx)(m,{title:`PriceTag`,shape:`process`,children:(0,x.jsx)(`p`,{children:`show(100) обращается к self.formatter`})}),(0,x.jsx)(f,{forward:`format(100)`,reverse:`«Цена: 100»`}),(0,x.jsx)(m,{title:`PriceFormatter`,shape:`process`,children:(0,x.jsx)(`p`,{children:`format(amount) возвращает текст`})})]})}),(0,x.jsxs)(`p`,{children:[(0,x.jsx)(`code`,{children:`PriceTag`}),` не становится форматировщиком и не копирует его. Атрибут `,(0,x.jsx)(`code`,{children:`self.formatter`}),`хранит ссылку на тот же объект, который мы передали снаружи; это можно проверить оператором `,(0,x.jsx)(`code`,{children:`is`}),`. Аналогия с принтером помогает разделить обязанности, но объекты Python не становятся физическими устройствами.`]}),(0,x.jsx)(b,{caption:`Два объекта, одна ссылка и один наблюдаемый вызов`,code:`class PriceFormatter:
    def format(self, amount):
        return f"Цена: {amount}"

class PriceTag:
    def __init__(self, formatter):
        self.formatter = formatter

    def show(self, amount):
        return self.formatter.format(amount)

f = PriceFormatter()
tag = PriceTag(f)
print(tag.show(100))
print(tag.formatter is f)`}),(0,x.jsxs)(`p`,{children:[`Первая строка создаёт `,(0,x.jsx)(`code`,{children:`f`}),`. Конструктор `,(0,x.jsx)(`code`,{children:`PriceTag(f)`}),` кладёт ссылку на `,(0,x.jsx)(`code`,{children:`f`}),`в `,(0,x.jsx)(`code`,{children:`tag.formatter`}),`. При `,(0,x.jsx)(`code`,{children:`tag.show(100)`}),` выполняется именно `,(0,x.jsx)(`code`,{children:`f.format(100)`}),`. Получаем две строки: `,(0,x.jsx)(`code`,{children:`Цена: 100`}),` и `,(0,x.jsx)(`code`,{children:`True`}),`. Проверка `,(0,x.jsx)(`code`,{children:`is`}),` подтверждает, что это тот же форматировщик, а не его копия. Сам `,(0,x.jsx)(`code`,{children:`tag`}),` и `,(0,x.jsx)(`code`,{children:`f`}),` разные объекты.`]}),(0,x.jsx)(d,{code:`print(tag.show(250))`,output:`Цена: 250`,hint:`PriceTag вызывает format у прежнего объекта f, но передаёт ему новое число.`}),(0,x.jsxs)(`p`,{children:[`При новом аргументе меняется текст, хотя связь между объектами остаётся прежней. Следующий шаг труднее: поменяем форматировщик, сохранив метод `,(0,x.jsx)(`code`,{children:`show`}),` у ценника. Для этого понадобится понятный обоим участникам договор о методе и результате.`]})]}),(0,x.jsxs)(s,{number:`03`,title:`Заменяемая зависимость должна выполнять нужное действие`,children:[(0,x.jsxs)(o,{children:[`Чтобы заменить зависимость, договоримся о её поведении. `,(0,x.jsx)(`code`,{children:`PriceTag.show(amount)`}),` ожидает метод `,(0,x.jsx)(`code`,{children:`format(amount)`}),`: передаём число и получаем строку для показа. Код внутри форматировщика может быть другим; способ обращения потребителя должен оставаться прежним.`]}),(0,x.jsxs)(`p`,{children:[`Добавим `,(0,x.jsx)(`code`,{children:`CompactPriceFormatter`}),` с тем же методом. Для числа 100 он возвращает`,(0,x.jsx)(`code`,{children:`100 ₽`}),`. Мы создаём `,(0,x.jsx)(`code`,{children:`other_tag = PriceTag(CompactPriceFormatter())`}),` и вызываем`,(0,x.jsx)(`code`,{children:`other_tag.show(100)`}),`: получаем `,(0,x.jsx)(`code`,{children:`100 ₽`}),`. Метод `,(0,x.jsx)(`code`,{children:`PriceTag.show`}),` не менялся. И в первом, и во втором случае он вызывает `,(0,x.jsx)(`code`,{children:`self.formatter.format(amount)`}),`.`]}),(0,x.jsx)(b,{caption:`Другая реализация того же договора`,code:`class CompactPriceFormatter:
    def format(self, amount):
        return f"{amount} ₽"

other_tag = PriceTag(CompactPriceFormatter())
print(other_tag.show(100))`}),(0,x.jsxs)(`p`,{children:[`Договор включает не только название метода: `,(0,x.jsx)(`code`,{children:`format`}),` принимает подходящий аргумент и возвращает строку. Если вариант вместо строки вернёт число, Python разрешит вызов, но ценник уже не получит текст нужного вида. А если метод называется `,(0,x.jsx)(`code`,{children:`render`}),`, вызов `,(0,x.jsx)(`code`,{children:`format`}),` вообще не найдётся. Найдём такой сбой в коде до просмотра объяснения:`]}),(0,x.jsx)(n,{code:`class WrongFormatter:
    def render(self, amount):
        return f"Цена: {amount}"

tag = PriceTag(WrongFormatter())
print(tag.show(100))`,question:`Почему вызов tag.show(100) завершится ошибкой AttributeError?`,options:[`PriceTag вызывает format, а WrongFormatter предоставляет только render`,`PriceTag хранит ссылку на отдельный объект`,`render возвращает строку, а не число`],correctIndex:0,explanation:`У WrongFormatter нет метода format. Ошибка возникает в self.formatter.format(amount), когда show пытается выполнить отсутствующий вызов.`,fix:`def format(self, amount):
    return f"Цена: {amount}"`}),(0,x.jsxs)(`p`,{children:[`Передача объекта в конструктор не проверяет договор автоматически. Python обнаруживает отсутствующий метод лишь при попытке его вызвать. Исправить можно сам вариант, дав ему `,(0,x.jsx)(`code`,{children:`format`}),`, либо заменить его совместимым объектом; менять `,(0,x.jsx)(`code`,{children:`PriceTag.show`}),` для каждого варианта не требуется.`]}),(0,x.jsx)(t,{rows:[[`format(100) → «Цена: 100»`,`Совместимо: метод есть, результат строка.`],[`format(100) → «100 ₽»`,`Совместимо: оформление меняется, договор сохраняется.`],[`render(100) → строка`,`Несовместимо: PriceTag вызывает другое имя.`],[`format(100) → 100`,`Нарушен договор результата: пришло число вместо строки.`]]}),(0,x.jsx)(l,{statement:(0,x.jsxs)(x.Fragment,{children:[`Если два форматировщика поддерживают `,(0,x.jsx)(`code`,{children:`format(amount)`}),` и возвращают строку, один из них обязательно должен наследоваться от другого.`]}),isTrue:!1,explanation:`Для вызова важен договор поведения, а не родительский класс. PriceTag ничего не знает о наследовании двух форматировщиков.`}),(0,x.jsx)(`p`,{children:`Проверим границу: классы могут вообще не иметь общего родителя, написанного нами, и всё равно удовлетворять этому договору. Формальные интерфейсы здесь не нужны. В практике мы перенесём идею на заголовок карточки, поэтому готового решения для него в теории пока нет.`})]}),(0,x.jsxs)(s,{number:`04`,title:`Отношение «использует» не равно «является»`,children:[(0,x.jsx)(o,{children:`Наследование уместно, когда новый тип действительно является разновидностью базового типа. Композиция описывает другую связь: один объект пользуется возможностью другого. В Planner эти слова помогают не переносить ответственность между моделью, хранением и интерфейсом.`}),(0,x.jsx)(`p`,{children:`Представим книгу на полке. Книга находится на полке и может быть положена на другую, но от этого книга не становится разновидностью мебели для хранения. Так же Task может быть сохранена через компонент хранения, но не становится разновидностью storage. Аналогия показывает только различие двух отношений; в программе решение всё равно сверяем с обязанностями и вызываемым поведением.`}),(0,x.jsx)(`p`,{children:`Вызов метода другого объекта ещё не требует, чтобы вызывающий объект создавал его внутри себя. Передача зависимости снаружи делает выбор заметным и позволяет заменить вариант. Но это решение не бесплатно: теперь потребитель зависит от имени метода и нужного ему поведения. Если альтернативы нет и отдельная ответственность не появляется, дополнительный объект может лишь усложнить путь чтения.`}),(0,x.jsx)(t,{rows:[[`PriceTag использует PriceFormatter`,`Ценник вызывает format у другого объекта; это композиция.`],[`Task использует хранение`,`Запись можно передать функции сохранения; Task не является storage.`],[`Task является storage`,`Ложное утверждение: назначение задачи и хранилища различается.`]]}),(0,x.jsx)(`p`,{children:`Наследование также добавляет связь между типами: новый тип заявляет, что является разновидностью другого и получает его поведение. Переиспользовать одну удобную функцию или связать данные с файлом недостаточно для такого утверждения. Если Task унаследует storage, читатель кода получит неверную картину: задача будет выглядеть частным видом хранилища, хотя её роль другая. Сначала называем отношение словами, затем выбираем механизм, который это отношение действительно выражает.`}),(0,x.jsx)(r,{tone:`info`,children:`Вспомним границу: композиция объясняет сотрудничество уже выбранных объектов. Она сама по себе не требует создавать абстрактный базовый класс, фабрику, контейнер зависимостей или новый сервис.`})]}),(0,x.jsxs)(s,{number:`05`,title:`Распределяем роли Planner без преждевременной реализации`,children:[(0,x.jsx)(o,{children:`Теперь применим критерии к знакомому проекту. Мы уже знаем его части по функциональному пути, но будущие классы сервиса и хранения пока не созданы. Карта ответственности помогает спланировать интеграцию, не выдавая план за готовый код.`}),(0,x.jsxs)(`p`,{children:[`Проследим знакомую команду `,(0,x.jsx)(`code`,{children:`done`}),` в текущем функциональном пути. CLI читает команду, операция ищет нужную запись в списке и меняет поле словаря, затем функция хранения записывает данные в JSON. Это маршрут через словари: подготовленная модель Task сама по себе не подключает методы к CLI.`]}),(0,x.jsx)(`p`,{children:`По плану следующего занятия операция сможет передать изменение статуса методу конкретной Task, а функциональный путь сохранения сможет использовать её преобразование в словарь. Список по-прежнему относится ко всему Planner, а выбор JSON-файла остаётся обязанностью хранения. Сверим роли в карте:`}),(0,x.jsx)(t,{rows:[[`Task`,`Описывает одну задачу, её состояние и локальные действия.`],[`storage`,`Восстанавливает и сохраняет записи; рабочий путь пока остаётся функциональным.`],[`будущий сервис`,`Позднее будет координировать операцию над набором задач.`],[`CLI`,`Принимает команды и показывает результаты пользователю.`]]}),(0,x.jsx)(r,{tone:`info`,children:`Сейчас: CLI → операции над словарями → функции JSON. Отдельно по маршруту подготовлена Task в app.models. Далее планируется подключить Task к операциям и функциональному хранению; классы хранения и координирующий сервис относятся к более поздним шагам.`}),(0,x.jsx)(`p`,{children:`Представим четыре отделения мастерской. Карточка заказа хранит состояние одной работы, инструмент выполняет отдельную операцию, складская ведомость отвечает за учёт, а стойка общения принимает запросы. Передача заказа между отделениями не превращает карточку в склад или стойку. Аналогия помогает удержать границы, но реальный Planner состоит из функций и модулей, и нам не нужно назначать каждому отделению класс.`})]}),(0,x.jsxs)(s,{number:`06`,title:`Карта будущих связей не означает готовую реализацию`,children:[(0,x.jsx)(o,{children:`Мы распределили ответственность, но пока не собираем новые классы из этой карты. Название роли помогает объяснить, что компонент будет делать; оно ещё не доказывает, что такой объект существует в рабочем пути.`}),(0,x.jsx)(`p`,{children:`По маршруту блока 7 хранение пока выполняют функции, а Task подготовлена как отдельная модель. Следующий этап включает её в операции и существующий путь JSON. Лишь позднее можно будет рассматривать, полезен ли сервисный объект, который получает компонент хранения и координирует действия над набором. Композиция станет уместна, если один объект действительно вызывает поведение другого, а не потому, что два имени стоят рядом на схеме.`}),(0,x.jsx)(`p`,{children:`Такое разделение защищает нас от двух ошибок. Первая: объявить будущее устройство уже внедрённым. Вторая: добавить класс только потому, что в архитектурной карте есть отдельная роль. Мы сначала сохраняем работающий путь и меняем конкретный компонент в согласованном шаге; архитектура описывает нужную связь, а код подтверждает, что она действительно появилась.`}),(0,x.jsx)(r,{tone:`info`,children:`В этом занятии мы объясняем композицию на отдельном примере, но не создаём PlannerService, storage-класс, контейнер зависимостей или новые команды CLI.`})]}),(0,x.jsxs)(s,{number:`07`,title:`Проверим выбор на спорных решениях`,children:[(0,x.jsx)(o,{children:`Теперь применим те же вопросы к трём предложениям: какую ответственность оно добавляет, какое отношение заявляет и есть ли для этой формы самостоятельная причина?`}),(0,x.jsx)(g,{prompt:`Соединим спорное решение с тем, что в нём не сходится.`,leftTitle:`Предложение`,rightTitle:`Причина сомнения`,pairs:[{left:`Сделать normalize_title отдельным классом`,right:`Для преобразования без своего состояния достаточно функции`},{left:`Унаследовать Task от storage`,right:`Задача сохраняется через storage, но не является хранилищем`},{left:`Хранить все задачи внутри одной Task`,right:`Одна модель описывает одну запись, а не весь набор Planner`}],explanation:`Мы проверили каждый выбор по ответственности: функция не получает лишний объект, Task сохраняет роль одной модели, а обязанности всего набора остаются выше.`}),(0,x.jsx)(`p`,{children:`В спорных решениях часто встречается одна и та же подмена: удобство реализации принимают за правильное отношение. Общая строка данных не делает типы родственниками, а совместный путь не означает, что один компонент должен вобрать обязанности другого. Если назначение класса трудно объяснить одним действием и его состоянием, мы возвращаемся к более простой форме и сравниваем результат.`}),(0,x.jsx)(v,{question:`Изменим условие: нужно показать число задач в меню. Какая часть Planner должна узнать размер набора и почему не одна Task?`,hint:`Для количества нужен весь список, а CLI отвечает за вывод. Одна Task знает только о себе.`,answer:(0,x.jsx)(`p`,{children:`Операция над набором может вычислить количество задач, а CLI показывает число в меню. Одна Task не знает о соседних задачах. Это новая задача для уже существующего уровня операций и вывода; добавлять общий список внутрь каждого экземпляра Task не нужно.`})})]}),(0,x.jsxs)(s,{number:`08`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(o,{children:`Короткое исследование перенесёт композицию на отдельный пример, а затем мы применим те же вопросы к Planner. Здесь важен наблюдаемый вызов зависимости и объяснение границ, а не новый слой кода проекта.`}),(0,x.jsx)(p,{variant:`connected`,items:[{title:`Передадим зависимость потребителю`,description:`Свяжем Preview и PlainFormatter: show(«План») вернёт «План», ссылка укажет на тот же объект.`},{title:`Подменим совместимый вариант`,description:`BracketFormatter даст «[План]» без правки show; отдельно проверим пустую строку.`},{title:`Проверим сломанный договор`,description:`Отсутствие format вызовет ошибку; вернём совместимый вариант и объясним ссылку.`},{title:`Разберём роли Planner`,description:`Разберём три решения и роли Task, операций, хранения, будущего сервиса и CLI.`}]}),(0,x.jsxs)(`p`,{children:[`После наблюдений проверим новый формат `,(0,x.jsx)(`code`,{children:`«Тема: План»`}),` и предскажем, какая ссылка должна измениться. Исследование не меняет Task, рабочий CLI или JSON: в следующем занятии подготовленную модель подключат к операциям. Здесь проверяем, что можем объяснить каждую границу до такого изменения.`]})]})]})}export{S as Lesson35};